from typing import Callable, Optional, List, Dict

Truth = Callable[[int], bool]
Oracle = Callable[[int], Optional[bool]]

def perfect(oracle: Oracle, truth: Truth, upto: int) -> bool:
    return all(oracle(n) == truth(n) for n in range(upto))

def build_defeating_truth(prefix: List[bool], family: List[Oracle]) -> Truth:
    plan: Dict[int, bool] = {n: prefix[n] for n in range(len(prefix))}
    slot = len(prefix)
    for O in family:
        verdict = O(slot)
        plan[slot] = (not verdict) if verdict is not None else True
        slot += 1
    return lambda n: plan.get(n, False)

if __name__ == "__main__":
    prefix = [True, False, True, True, False]
    family: List[Oracle] = [
        lambda n: True,
        lambda n: False,
        lambda n: (n % 2 == 0),
        lambda n: None if n > 7 else True,
        lambda n: (n * n % 5 == 1),
    ]
    T = build_defeating_truth(prefix, family)
    horizon = len(prefix) + len(family) + 3
    print("extends prefix:", all(T(n) == prefix[n] for n in range(len(prefix))))
    print("all oracles defeated:", all(not perfect(O, T, horizon) for O in family))

import random
from typing import Callable, Optional, List

Truth = Callable[[int], bool]
Oracle = Callable[[int], Optional[bool]]

def perfect(oracle: Oracle, truth: Truth, upto: int) -> bool:
    return all(oracle(n) == truth(n) for n in range(upto))

def covered_fraction(num_worlds: int = 100_000, upto: int = 40) -> float:
    rng = random.Random(12345)
    family: List[Oracle] = [
        lambda n: True, lambda n: False,
        lambda n: (n % 2 == 0), lambda n: (n % 3 == 0),
    ]
    covered = 0
    for _ in range(num_worlds):
        bits = [bool(rng.getrandbits(1)) for _ in range(upto)]
        T: Truth = lambda n, b=bits: b[n]
        if any(perfect(O, T, upto) for O in family):
            covered += 1
    return covered / num_worlds

if __name__ == "__main__":
    print("covered fraction:", covered_fraction())

import random
from typing import Callable, Optional, Dict

Truth = Callable[[int], bool]
Oracle = Callable[[int], Optional[bool]]

def perfect(oracle: Oracle, truth: Truth, upto: int) -> bool:
    return all(oracle(n) == truth(n) for n in range(upto))

def fingerprint_check(upto: int = 64) -> int:
    rng = random.Random(0)
    world: Dict[int, bool] = {n: bool(rng.getrandbits(1)) for n in range(upto)}
    O: Oracle = lambda n: world[n]
    T: Truth = lambda n: world[n]
    assert perfect(O, T, upto)
    fails = 0
    for flip in range(upto):
        w2 = dict(world); w2[flip] = not w2[flip]
        if not perfect(O, lambda n, w=w2: w[n], upto):
            fails += 1
    return fails

if __name__ == "__main__":
    print("worlds defeated after one flip:", fingerprint_check(), "/ 64")

