function BUILD_DEFEATING_TRUTH(prefix sigma[0..m-1], oracles O[0..k-1]):
    plan <- empty map
    for n in 0..m-1:
        plan[n] <- sigma[n]              # stay inside the cylinder [sigma]
    slot <- m
    for i in 0..k-1:
        v <- O[i](slot)                  # oracle i's verdict at a fresh slot
        if v is UNKNOWN:
            plan[slot] <- TRUE           # any definite value defeats 'unknown'
        else:
            plan[slot] <- NOT v          # diagonalize: disagree with O[i]
        slot <- slot + 1
    return function T(n): return plan[n] if n in plan else FALSE

