from typing import Callable, Optional, List, Dict

Truth = Callable[[int], bool]
Oracle = Callable[[int], Optional[bool]]

def build_defeating_truth(prefix: List[bool], family: List[Oracle]) -> Truth:
    """Return a ground truth extending `prefix` that no oracle in `family` decides
    perfectly (block diagonalization)."""
    plan: Dict[int, bool] = {n: prefix[n] for n in range(len(prefix))}
    slot: int = len(prefix)
    for oracle in family:
        verdict: Optional[bool] = oracle(slot)
        plan[slot] = (not verdict) if verdict is not None else True
        slot += 1
    def T(n: int) -> bool:
        return plan.get(n, False)
    return T

algorithms.pseudocode:
function PERFECT(O, T, H):
    for n in 0..H-1:
        if O(n) != T(n): return FALSE
    return TRUE

function UNIQUE_WORLD(O, worlds, H):
    winners <- [ T for T in worlds if PERFECT(O, T, H) ]
    return length(winners) <= 1        # subsingleton perfect set

