Truth = Callable[[int], bool]
Oracle = Callable[[int], Optional[bool]]

def perfect(oracle: Oracle, truth: Truth, horizon: int) -> bool:
    return all(oracle(n) == truth(n) for n in range(horizon))

def unique_world(oracle: Oracle, worlds: List[Truth], horizon: int) -> bool:
    winners = [T for T in worlds if perfect(oracle, T, horizon)]
    return len(winners) <= 1

