function ENUMERATE_CODES(N, H):
    seen <- empty map (behaviour -> code)
    for code in 0..N-1:
        O <- PROGRAM(code)               # decode program `code` into an oracle
        behaviour <- ( O(0), O(1), ..., O(H-1) )
        if behaviour not in seen:
            seen[behaviour] <- code       # first (least) code for this oracle
    return seen                          # injective: behaviour -> code

