from typing import Callable, Dict, Tuple

Oracle = Callable[[int], bool]

def program(code: int) -> Oracle:
    """A toy effective enumeration: code `code` defines a total oracle."""
    return lambda n: bool((code >> (n % 6)) & 1)

def enumerate_codes(num_codes: int, horizon: int) -> Dict[Tuple[bool, ...], int]:
    seen: Dict[Tuple[bool, ...], int] = {}
    for code in range(num_codes):
        O = program(code)
        behaviour = tuple(O(n) for n in range(horizon))
        if behaviour not in seen:
            seen[behaviour] = code
    return seen
